modules/vpc-control-plane/peering.tf: resource "aws_vpc_peering_connection" "control_plane_peer" {
  peer_owner_id = var.peer_account_id
  peer_vpc_id   = var.peer_vpc_id
  vpc_id        = var.vpc_id
}
resource "aws_route" "peer_routes" {
  count = length(var.route_tables)
  route_table_id = var.route_tables[count.index]
  destination_cidr_block = var.peer_cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.control_plane_peer.id
}"
